svg.script:

(function() {
  var root = document.getElementById('a12p15b-svg');

  // Banco de dados anatômico determinístico por feixe
  var bundleData = {
    puborretal: {
      title: "MÚSCULO PUBORRETAL",
      prefix: "PUBO-",
      prefixDesc: "(Púbis)",
      suffix: "-RRETAL",
      suffixDesc: "(Alça atrás do Reto)",
      color: "var(--a12p15b-puborretal)",
      origem: "Face posterior do corpo do púbis (bilateral)",
      destino: "Alça muscular contínua contornando a junção anorretal",
      mecanismo: "Traciona o reto anteriorizando-o. Esfíncter mecânico principal: agudiza o ângulo anorretal (92° Laxe ➔ 70° Contração).",
      angle: "70°",
      arcD: "M 292 272 A 40 40 0 0 1 245 375"
    },
    pubococcigeo: {
      title: "MÚSCULO PUBOCOCCÍGEO",
      prefix: "PUBO-",
      prefixDesc: "(Púbis)",
      suffix: "-COCCÍGEO",
      suffixDesc: "(Cóccix / Rafe)",
      color: "var(--a12p15b-pubococcigeo)",
      origem: "Face posterior do púbis (lateral ao puborretal)",
      destino: "Cóccix e ligamento anococcígeo (rafe mediana)",
      mecanismo: "Sustentação direta das vísceras pélvicas sexuais e urinárias. Eleva o assoalho pélvico no sentido ântero-superior.",
      angle: "92°",
      arcD: "M 292 272 A 40 40 0 0 1 258 385"
    },
    iliococcigeo: {
      title: "MÚSCULO ILIOCOCCÍGEO",
      prefix: "ILIO-",
      prefixDesc: "(Arco Tendíneo / Ílio)",
      suffix: "-COCCÍGEO",
      suffixDesc: "(Cóccix)",
      color: "var(--a12p15b-iliococcigeo)",
      origem: "Arco tendíneo do músculo elevador do ânus (ATFP) e espinha isquiática",
      destino: "Últimos segmentos do cóccix e rafe anococcígea",
      mecanismo: "Forma o diafragma muscular posterior rígido (plano inclinado). Suporta a pressão intra-abdominal sustentada.",
      angle: "92°",
      arcD: "M 292 272 A 40 40 0 0 1 258 385"
    },
    coccigeo: {
      title: "MÚSCULO COCCÍGEO (ISQUIOCOCCÍGEO)",
      prefix: "ISQUIO / ILIO-",
      prefixDesc: "(Espinha Isquiática)",
      suffix: "-COCCÍGEO",
      suffixDesc: "(Sacro e Cóccix)",
      color: "var(--a12p15b-coccigeo)",
      origem: "Espinha isquiática e superfície profunda do ligamento sacroespinal",
      destino: "Bordas laterais do segmento inferior do sacro e cóccix",
      mecanismo: "Traciona o cóccix anteriormente após a defecação/parto. Estabiliza a articulação sacroatóide posterior.",
      angle: "92°",
      arcD: "M 292 272 A 40 40 0 0 1 258 385"
    }
  };

  // Elementos da Interface
  var displayTitle = document.getElementById('a12p15b-display-title');
  var displayPrefix = document.getElementById('a12p15b-display-prefix');
  var displaySuffix = document.getElementById('a12p15b-display-suffix');
  var displayOrigem = document.getElementById('a12p15b-display-origem');
  var displayDestino = document.getElementById('a12p15b-display-destino');
  var displayMecanismo = document.getElementById('a12p15b-display-mecanismo');
  var angleValue = document.getElementById('a12p15b-angle-value');
  var angleArc = document.getElementById('a12p15b-angle-arc-path');

  var vectors = [
    'a12p15b-vec-puborretal-sag', 'a12p15b-vec-pubococcigeo-sag', 'a12p15b-vec-iliococcigeo-sag', 'a12p15b-vec-coccigeo-sag',
    'a12p15b-vec-puborretal-inf', 'a12p15b-vec-pubococcigeo-inf', 'a12p15b-vec-iliococcigeo-inf', 'a12p15b-vec-coccigeo-inf'
  ];

  function selectBundle(bundleKey) {
    var data = bundleData[bundleKey];
    if (!data) return;

    // Atualiza Estado na Raiz SVG
    root.setAttribute('data-active-bundle', bundleKey);

    // Atualiza Textos do Painel Interativo
    displayTitle.textContent = data.title + " (SELECIONADO)";
    displayPrefix.textContent = data.prefix;
    displayPrefix.setAttribute('fill', data.color);
    displaySuffix.textContent = data.suffix;
    displaySuffix.setAttribute('fill', data.color);

    displayOrigem.textContent = data.origem;
    displayDestino.textContent = data.destino;
    displayMecanismo.textContent = data.mecanismo;

    // Animação Dinâmica do Ângulo Anorretal
    angleValue.textContent = data.angle;
    if (angleArc) {
      angleArc.setAttribute('d', data.arcD);
    }

    // Ativação dos Vetores tracejados em movimento
    vectors.forEach(function(id) {
      var vec = document.getElementById(id);
      if (vec) {
        if (id.indexOf(bundleKey) !== -1) {
          vec.classList.add('a12p15b-vector-active');
        } else {
          vec.classList.remove('a12p15b-vector-active');
        }
      }
    });
  }

  // Event Listeners para Clique e Teclado
  var bundles = document.querySelectorAll('.a12p15b-bundle');
  bundles.forEach(function(el) {
    var key = el.getAttribute('data-bundle');

    el.addEventListener('click', function() {
      selectBundle(key);
    });

    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        selectBundle(key);
      }
    });
  });

  // Inicializa com Puborretal Ativo por Padrão
  selectBundle('puborretal');
})();
